<?php

/**
 * @file
 * A standalone, self-contained fake DrupalForge migration API server.
 *
 * Implements the 6 contract endpoints from
 * DrupalForge_DevPanel_Migration_Implementation_Plan.md §4 plus a companion
 * /storage/{key} object-storage endpoint (standing in for presigned S3 PUT
 * URLs) against a single JSON file as its state store. Used exclusively by
 * scripts/smoke/run.sh for a real end-to-end HTTP smoke test - this is test
 * infrastructure, not part of the module's runtime.
 *
 * Serves real HTTPS (a self-signed cert generated by run.sh), not plain
 * HTTP: DrupalForgeClient::assertHttps() rejects any non-HTTPS base URL, and
 * this smoke test must exercise the real client code, not a weakened path
 * around it. PHP's built-in `php -S` dev server has no TLS support, so this
 * is a small raw stream_socket_server() HTTP/1.1 server instead - single
 * connection at a time (fine: run.sh drives everything sequentially),
 * Connection: close on every response (simplest correct way to avoid
 * implementing HTTP keep-alive), and explicit `100 Continue` handling for
 * request bodies over cURL's ~1MiB Expect threshold (without this, a
 * multipart PUT of a part above that size deadlocks: curl waits for "100
 * Continue" before sending the body, this server would otherwise be stuck
 * reading a body that was never sent).
 */

declare(strict_types=1);

error_reporting(E_ALL);
ini_set('display_errors', '1');

$host = getenv('FAKE_API_HOST') ?: '127.0.0.1';
$port = (int) (getenv('FAKE_API_PORT') ?: 8199);
$stateDir = rtrim(getenv('FAKE_API_STATE_DIR') ?: sys_get_temp_dir() . '/drupalforge-migrate-smoke', '/');
$secret = getenv('FAKE_API_SECRET') ?: 'smoke-secret';
$certFile = getenv('FAKE_API_CERT') ?: $stateDir . '/cert.pem';
$keyFile = getenv('FAKE_API_KEY') ?: $stateDir . '/key.pem';
$multipartThreshold = (int) (getenv('FAKE_API_MULTIPART_THRESHOLD') ?: 1048576);
$partSize = (int) (getenv('FAKE_API_PART_SIZE') ?: 786432);
$maxBackups = (int) (getenv('FAKE_API_MAX_BACKUPS') ?: 3);

$objectsDir = $stateDir . '/objects';
$stateFile = $stateDir . '/state.json';
$logFile = $stateDir . '/requests.log';
$failFlagFile = $stateDir . '/fail_flag.json';

@mkdir($stateDir, 0700, TRUE);
@mkdir($objectsDir, 0700, TRUE);

if (!is_file($certFile) || !is_file($keyFile)) {
  fwrite(STDERR, "Missing cert/key at {$certFile} / {$keyFile}. Generate them first (see run.sh).\n");
  exit(1);
}

// --- State helpers -----------------------------------------------------

function load_state(string $stateFile): array {
  if (!is_file($stateFile)) {
    return ['reservations' => []];
  }
  $raw = @file_get_contents($stateFile);
  $data = $raw !== FALSE ? json_decode($raw, TRUE) : NULL;
  return \is_array($data) ? $data : ['reservations' => []];
}

function save_state(string $stateFile, array $state): void {
  file_put_contents($stateFile, json_encode($state, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE), LOCK_EX);
}

function log_event(string $logFile, string $endpoint, string $backupId, string $extra = '-'): void {
  $line = sprintf("%d\t%s\t%s\t%s\n", time(), $endpoint, $backupId !== '' ? $backupId : '-', $extra);
  file_put_contents($logFile, $line, FILE_APPEND | LOCK_EX);
}

function reset_all(string $stateDir, string $stateFile, string $logFile, string $failFlagFile, string $objectsDir): void {
  save_state($stateFile, ['reservations' => []]);
  file_put_contents($logFile, '');
  @unlink($failFlagFile);
  foreach ((array) glob($objectsDir . '/*') as $f) {
    @unlink($f);
  }
}

// --- Minimal HTTP/1.1-over-TLS server -----------------------------------

$context = stream_context_create();
stream_context_set_option($context, 'ssl', 'local_cert', $certFile);
stream_context_set_option($context, 'ssl', 'local_pk', $keyFile);
stream_context_set_option($context, 'ssl', 'allow_self_signed', TRUE);
stream_context_set_option($context, 'ssl', 'verify_peer', FALSE);
stream_context_set_option($context, 'ssl', 'verify_peer_name', FALSE);

$server = stream_socket_server(
  "ssl://{$host}:{$port}",
  $errno,
  $errstr,
  STREAM_SERVER_BIND | STREAM_SERVER_LISTEN,
  $context,
);
if ($server === FALSE) {
  fwrite(STDERR, "Failed to start server: {$errstr} ({$errno})\n");
  exit(1);
}
fwrite(STDERR, "fake-drupalforge-api listening on https://{$host}:{$port} (state: {$stateDir})\n");

/**
 * Reads the request line + headers (up to the blank line), returning
 * [method, path, query, headers (lowercase keys)] or NULL on EOF/error.
 */
function read_request_head($conn): ?array {
  $requestLine = fgets($conn, 8192);
  if ($requestLine === FALSE || $requestLine === '') {
    return NULL;
  }
  if (!preg_match('#^(\S+)\s+(\S+)\s+HTTP/1\.\d#', $requestLine, $m)) {
    return NULL;
  }
  $method = $m[1];
  $target = $m[2];
  $parts = parse_url($target);
  $path = $parts['path'] ?? '/';

  $headers = [];
  while (TRUE) {
    $line = fgets($conn, 8192);
    if ($line === FALSE) {
      break;
    }
    $line = rtrim($line, "\r\n");
    if ($line === '') {
      break;
    }
    $pos = strpos($line, ':');
    if ($pos === FALSE) {
      continue;
    }
    $name = strtolower(trim(substr($line, 0, $pos)));
    $value = trim(substr($line, $pos + 1));
    $headers[$name] = $value;
  }

  return [$method, $path, $headers];
}

function read_body($conn, array $headers): string {
  if (strtolower($headers['expect'] ?? '') === '100-continue') {
    fwrite($conn, "HTTP/1.1 100 Continue\r\n\r\n");
  }
  $length = (int) ($headers['content-length'] ?? 0);
  if ($length <= 0) {
    return '';
  }
  $body = '';
  while (\strlen($body) < $length) {
    $chunk = fread($conn, min(65536, $length - \strlen($body)));
    if ($chunk === FALSE || $chunk === '') {
      break;
    }
    $body .= $chunk;
  }
  return $body;
}

/**
 * @param array<string, string> $headers
 */
function write_response($conn, int $status, array $headers, string $body): void {
  $reason = [
    200 => 'OK', 201 => 'Created', 204 => 'No Content',
    400 => 'Bad Request', 401 => 'Unauthorized', 404 => 'Not Found',
    409 => 'Conflict', 500 => 'Internal Server Error',
  ][$status] ?? 'OK';
  $headers['Content-Length'] = (string) \strlen($body);
  $headers['Connection'] = 'close';
  $out = "HTTP/1.1 {$status} {$reason}\r\n";
  foreach ($headers as $name => $value) {
    $out .= "{$name}: {$value}\r\n";
  }
  $out .= "\r\n" . $body;
  fwrite($conn, $out);
}

function write_json($conn, int $status, array $data): void {
  write_response($conn, $status, ['Content-Type' => 'application/json'], json_encode($data, JSON_UNESCAPED_SLASHES));
}

// --- Request dispatch ----------------------------------------------------

/**
 * @return void
 */
function handle_request($conn, string $method, string $path, array $headers, string $rawBody, array $env): void {
  ['stateFile' => $stateFile, 'logFile' => $logFile, 'failFlagFile' => $failFlagFile,
    'objectsDir' => $objectsDir, 'secret' => $secret, 'host' => $host, 'port' => $port,
    'multipartThreshold' => $multipartThreshold, 'partSize' => $partSize, 'maxBackups' => $maxBackups,
    'stateDir' => $stateDir] = $env;

  if ($method === 'GET' && $path === '/health') {
    write_json($conn, 200, ['ok' => TRUE]);
    return;
  }

  if ($method === 'POST' && $path === '/admin/reset') {
    reset_all($stateDir, $stateFile, $logFile, $failFlagFile, $objectsDir);
    write_json($conn, 200, ['reset' => TRUE]);
    return;
  }

  if ($method === 'PUT' && str_starts_with($path, '/storage/')) {
    handle_storage_put($conn, $path, $rawBody, $objectsDir, $logFile, $failFlagFile);
    return;
  }

  if (!preg_match('#^/api/migration/v1/([^/]+)/(.*)$#', $path, $m)) {
    write_json($conn, 404, ['error' => 'not found']);
    return;
  }
  $migrationId = $m[1];
  $rest = $m[2];

  $expectedAuth = 'Bearer ' . $migrationId . '.' . $secret;
  if (($headers['authorization'] ?? '') !== $expectedAuth) {
    write_json($conn, 401, ['error' => 'unauthorized']);
    return;
  }

  $state = load_state($stateFile);

  if ($method === 'POST' && $rest === 'connect') {
    $backups = [];
    foreach ($state['reservations'] as $id => $r) {
      $backups[] = ['id' => $id, 'status' => $r['status'], 'expires' => $r['reserved_until']];
    }
    log_event($logFile, 'connect', '-');
    write_json($conn, 200, ['limits' => ['max_backups' => $maxBackups], 'backups' => $backups, 'status' => 'ok']);
    return;
  }

  if ($method === 'GET' && $rest === 'backups') {
    $backups = [];
    foreach ($state['reservations'] as $id => $r) {
      $backups[] = ['id' => $id, 'status' => $r['status'], 'expires' => $r['reserved_until']];
    }
    log_event($logFile, 'list_backups', '-');
    write_json($conn, 200, ['backups' => $backups]);
    return;
  }

  if ($method === 'POST' && $rest === 'backups') {
    $active = 0;
    foreach ($state['reservations'] as $r) {
      if (\in_array($r['status'], ['reserved', 'uploading'], TRUE)) {
        $active++;
      }
    }
    if ($active >= $maxBackups) {
      log_event($logFile, 'reserve_rejected', '-');
      write_json($conn, 409, ['error' => 'quota exceeded']);
      return;
    }
    $id = bin2hex(random_bytes(8));
    $reservedUntil = gmdate('c', time() + 3600);
    $state['reservations'][$id] = [
      'status' => 'reserved',
      'created' => time(),
      'reserved_until' => $reservedUntil,
      'artifacts' => [],
      'manifest' => NULL,
    ];
    save_state($stateFile, $state);
    log_event($logFile, 'reserve', $id);
    write_json($conn, 201, ['backup_id' => $id, 'reserved_until' => $reservedUntil]);
    return;
  }

  if ($method === 'POST' && preg_match('#^backups/([^/]+)/upload$#', $rest, $um)) {
    $id = $um[1];
    if (!isset($state['reservations'][$id])) {
      write_json($conn, 404, ['error' => 'unknown backup']);
      return;
    }
    $body = json_decode($rawBody, TRUE);
    if (!\is_array($body)) {
      write_json($conn, 400, ['error' => 'invalid body']);
      return;
    }
    $artifact = (string) ($body['artifact'] ?? '');
    $size = (int) ($body['size'] ?? 0);
    $sha256 = (string) ($body['sha256'] ?? '');
    $filename = (string) ($body['filename'] ?? '');

    if ($size > $multipartThreshold) {
      $numParts = (int) ceil($size / $partSize);
      $parts = [];
      for ($n = 1; $n <= $numParts; $n++) {
        $key = "{$id}_{$artifact}_part{$n}";
        $parts[] = ['n' => $n, 'url' => "https://{$host}:{$port}/storage/{$key}"];
      }
      $uploadId = bin2hex(random_bytes(4));
      $state['reservations'][$id]['artifacts'][$artifact] = [
        'size' => $size, 'sha256' => $sha256, 'filename' => $filename,
        'mode' => 'multipart', 'part_size' => $partSize, 'num_parts' => $numParts, 'upload_id' => $uploadId,
      ];
      $state['reservations'][$id]['status'] = 'uploading';
      save_state($stateFile, $state);
      log_event($logFile, 'upload_request', $id, "{$artifact}:multipart:{$numParts}");
      write_json($conn, 200, [
        'mode' => 'multipart', 'upload_id' => $uploadId, 'parts' => $parts,
        'part_size' => $partSize, 'expires' => gmdate('c', time() + 3600),
      ]);
    }
    else {
      $key = "{$id}_{$artifact}_single";
      $state['reservations'][$id]['artifacts'][$artifact] = [
        'size' => $size, 'sha256' => $sha256, 'filename' => $filename,
        'mode' => 'single', 'part_size' => 0, 'num_parts' => 0, 'upload_id' => NULL,
      ];
      $state['reservations'][$id]['status'] = 'uploading';
      save_state($stateFile, $state);
      log_event($logFile, 'upload_request', $id, "{$artifact}:single");
      write_json($conn, 200, [
        'mode' => 'single', 'url' => "https://{$host}:{$port}/storage/{$key}",
        'part_size' => 0, 'expires' => gmdate('c', time() + 3600),
      ]);
    }
    return;
  }

  if ($method === 'POST' && preg_match('#^backups/([^/]+)/complete$#', $rest, $cm)) {
    $id = $cm[1];
    if (!isset($state['reservations'][$id])) {
      write_json($conn, 404, ['error' => 'unknown backup']);
      return;
    }
    $body = json_decode($rawBody, TRUE);
    $artifacts = \is_array($body) ? ($body['artifacts'] ?? []) : [];

    foreach ($artifacts as $result) {
      $artifact = (string) ($result['artifact'] ?? '');
      $info = $state['reservations'][$id]['artifacts'][$artifact] ?? NULL;
      if ($info === NULL) {
        write_json($conn, 400, ['error' => "unknown artifact {$artifact}"]);
        return;
      }
      if ($info['mode'] === 'multipart') {
        $bytes = '';
        for ($n = 1; $n <= $info['num_parts']; $n++) {
          $p = $objectsDir . '/' . "{$id}_{$artifact}_part{$n}";
          if (!is_file($p)) {
            write_json($conn, 400, ['error' => "missing part {$n} for {$artifact}"]);
            return;
          }
          $bytes .= (string) file_get_contents($p);
        }
      }
      else {
        $p = $objectsDir . '/' . "{$id}_{$artifact}_single";
        if (!is_file($p)) {
          write_json($conn, 400, ['error' => "missing object for {$artifact}"]);
          return;
        }
        $bytes = (string) file_get_contents($p);
      }
      $actualSha256 = hash('sha256', $bytes);
      $expectedSha256 = (string) ($result['sha256'] ?? '');
      if ($actualSha256 !== $expectedSha256) {
        write_json($conn, 400, ['error' => "sha256 mismatch for {$artifact}: expected {$expectedSha256}, got {$actualSha256}"]);
        return;
      }
    }

    $state['reservations'][$id]['status'] = 'ready';
    $state['reservations'][$id]['manifest'] = \is_array($body) ? ($body['manifest'] ?? NULL) : NULL;
    save_state($stateFile, $state);
    log_event($logFile, 'complete', $id);
    write_json($conn, 200, ['status' => 'ready']);
    return;
  }

  if ($method === 'DELETE' && preg_match('#^backups/([^/]+)$#', $rest, $dm)) {
    $id = $dm[1];
    if (isset($state['reservations'][$id])) {
      foreach ((array) glob($objectsDir . '/' . $id . '_*') as $f) {
        @unlink($f);
      }
      unset($state['reservations'][$id]);
      save_state($stateFile, $state);
    }
    log_event($logFile, 'abort', $id);
    write_response($conn, 204, [], '');
    return;
  }

  write_json($conn, 404, ['error' => 'not found']);
}

function handle_storage_put($conn, string $path, string $rawBody, string $objectsDir, string $logFile, string $failFlagFile): void {
  $key = substr($path, \strlen('/storage/'));
  if (preg_match('/^(.+)_(code|db)_part(\d+)$/', $key, $m)) {
    $backupId = $m[1];
    $artifact = $m[2];
    $part = (int) $m[3];
  }
  elseif (preg_match('/^(.+)_(code|db)_single$/', $key, $m)) {
    $backupId = $m[1];
    $artifact = $m[2];
    $part = NULL;
  }
  else {
    write_json($conn, 400, ['error' => 'bad storage key']);
    return;
  }

  if (is_file($failFlagFile)) {
    $flag = json_decode((string) file_get_contents($failFlagFile), TRUE);
    if (\is_array($flag)) {
      $flagPart = (string) ($flag['part'] ?? '');
      $partMatches = $flagPart === 'any' || $flagPart === (string) ($part ?? 'single');
      if (($flag['artifact'] ?? NULL) === $artifact && $partMatches) {
        @unlink($failFlagFile);
        log_event($logFile, 'put_part_forced_failure', $backupId, "{$artifact}:" . ($part ?? 'single') . ':' . ($flag['status'] ?? 500));
        write_response($conn, (int) ($flag['status'] ?? 500), [], '');
        return;
      }
    }
  }

  file_put_contents($objectsDir . '/' . $key, $rawBody);
  $etag = md5($rawBody);
  log_event($logFile, 'put_part', $backupId, "{$artifact}:" . ($part ?? 'single'));
  write_response($conn, 200, ['ETag' => '"' . $etag . '"'], '');
}

$env = [
  'stateFile' => $stateFile,
  'logFile' => $logFile,
  'failFlagFile' => $failFlagFile,
  'objectsDir' => $objectsDir,
  'secret' => $secret,
  'host' => $host,
  'port' => $port,
  'multipartThreshold' => $multipartThreshold,
  'partSize' => $partSize,
  'maxBackups' => $maxBackups,
  'stateDir' => $stateDir,
];

while (TRUE) {
  $conn = @stream_socket_accept($server, -1);
  if ($conn === FALSE) {
    continue;
  }
  $head = read_request_head($conn);
  if ($head !== NULL) {
    [$method, $path, $headers] = $head;
    $body = ($method === 'POST' || $method === 'PUT') ? read_body($conn, $headers) : '';
    try {
      handle_request($conn, $method, $path, $headers, $body, $env);
    }
    catch (\Throwable $e) {
      fwrite(STDERR, 'Error handling request: ' . $e->getMessage() . "\n");
      @write_json($conn, 500, ['error' => $e->getMessage()]);
    }
  }
  fclose($conn);
}
